let state,envelopeToken=null,view='desk',selectedPerson='C02',sceneId=null,readingKey=null,journalTab='events',journalSearch='',saving='已存于本机',busy=false,aiStatus={configured:false},toastTimer;
let recoveryRaw=localStorage.getItem(STORAGE_KEY),initError=null;try{if(invalidContinuation)throw new RuleError('接续副本地址错误，请回原入口。');if(invalidCopy)throw new RuleError('迁移副本地址错误，请返回迁移管理。');const env=readEnvelope();if(env){state=env.state;envelopeToken=env.writeId;}else{if(continuationId)throw new RuleError('这份接续副本的自动档缺失，可从完整接续包或本副本手动档恢复。');if(copyId)throw new RuleError('这份副本的自动档缺失，可从手动档、恢复备份或迁移包恢复。');state=newGame();const saved=saveEnvelope(state,null);envelopeToken=saved.writeId;}}catch(err){initError=err;}
if(state&&state.sealed)view='chronicle';
