function reactionFrame(){return{state,storageKey:STORAGE_KEY,writeId:envelopeToken,visit:visitSerial,appVersion:VERSION,configVersion:getAIConfig().revision,view,sceneId,readingKey,sceneKey:sceneId?(readingKey||eventKey(state,sceneId)):null};}
function syncReactionView(){const identity=JSON.stringify([view,sceneId,readingKey,selectedPerson,state?.gameId]);if(identity!==lastReactionView){lastReactionView=identity;visitSerial++;reactions.cancel();cancelInput(false);}}
function reactionNote(t,key){const hint=reactionHint(t,!readingKey&&reactions.pendingKey()===key);return hint?'<p class="quiet-note">'+esc(hint)+'</p>':'';}
function toast(msg){$('#toast').textContent=uiReadingText(msg);$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function download(text,name,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function applyPrefs(){document.documentElement.style.setProperty('--body-size',`${prefs.font}px`);document.body.classList.toggle('portrait-hidden',prefs.hideArt);document.body.classList.toggle('reduced-motion',!prefs.motion);}
function savePrefs(){localStorage.setItem('changyong-display',JSON.stringify(prefs));applyPrefs();}
async function update(fn,{backup=false}={}){
 return exclusive(async()=>{
  const env=readEnvelope();if((env?.writeId||null)!==envelopeToken)throw new RuleError('另一窗口已更新进度。请载入最新自动档后再操作。','CONFLICT');
  const before=state,writeId=envelopeToken,next=await fn(before);if(state!==before||envelopeToken!==writeId)throw new RuleError('进度在等待期间已变化，请重新核对。','CONFLICT');if(backup)backupBeforeRestore();const saved=saveEnvelope(next,writeId);state=next;envelopeToken=saved.writeId;saving='刚刚存于本机';return {before,state};
 });
}
function showError(err){const message=err.message||'操作未完成。';toast(message);const feedback=modal.open?modal.querySelector('[data-operation-feedback]'):document.querySelector('#composer [data-operation-feedback]');if(feedback){feedback.textContent=message;feedback.setAttribute('role','alert');}if(err.code==='CONFLICT')saving='有更新 · 请重新载入';}
let compactDownloadURL=null,preparingCompact=false;
function prepareCompactDownload(){if(preparingCompact)return;preparingCompact=true;dialog('正在核对完整接续包','<p>核对精确原JSON和八槽，准备期间原档保持。完成后请点击明确的下载链接。</p>','');setTimeout(async()=>{try{const raw=await exportCompactContinuationBundle(continuationId),url=URL.createObjectURL(new Blob([raw],{type:'application/json'}));dialog('紧凑完整接续包已备好','<p>包含精确接续前原JSON及本副本全部八槽；下载与恢复均不裁剪历史正文。</p>',`<a class="primary-btn" id="compact-download" href="${url}" download="长雍紧凑接续包_${continuationId.slice(0,8)}.json">下载紧凑完整接续包</a>`);compactDownloadURL=url;$('#compact-download').onclick=()=>setTimeout(()=>{URL.revokeObjectURL(url);if(compactDownloadURL===url)compactDownloadURL=null;},3000);}catch(error){showError(error);}finally{preparingCompact=false;}},0);}

function closeModal(){if(committing)return;if(compactDownloadURL){URL.revokeObjectURL(compactDownloadURL);compactDownloadURL=null;}if(modal.open)modal.close();modal.innerHTML='';}
function dialog(title,body,actions){closeModal();modal.innerHTML=`<div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button data-close aria-label="关闭">×</button></div><div class="modal-scroll">${body}</div><p class="operation-feedback" data-operation-feedback role="status" aria-live="polite"></p><div class="modal-actions"><button class="secondary-btn" data-close>返回</button>${actions||''}</div>`;modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModal);applyReadingUi(modal);modal.showModal();bindArt();}
function tag(text,style=''){return `<span class="tag ${style}">${esc(text)}</span>`;}
function monogram(c){return `<span class="monogram" style="--person-color:${c.color}">${esc(c.sign)}</span>`;}
function heading(label,title,sub,right=''){return `<div class="page-heading"><div><div class="eyebrow">${esc(label)}</div><h1>${esc(title)}</h1><p>${esc(sub)}</p></div>${right}</div>`;}
function empty(title,text){return `<div class="empty"><strong>${esc(title)}</strong>${esc(text)}</div>`;}
function button(text,action,cls='secondary-btn',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${text}</button>`;}
function route(next){if(committing){toast('正在保存这次决定，请稍候。');return;}cancelInput(false);closeModal();view=next;sceneId=null;readingKey=null;render();window.scrollTo(0,0);}
function displayArt(){installArtFallbacks(document);}
function bindArt(){displayArt();document.querySelectorAll('[data-art-open]').forEach(b=>b.onclick=()=>{const a=artAsset(b.dataset.artOpen);if(!a)return;if(a.id.startsWith('cg_')&&!Object.values(state.transcripts).some(t=>illustrationAsset(t)?.id===a.id))return;dialog(a.name,renderArtwork(a,{role:'full',className:'art-full',caption:a.category==='portrait'?`档案肖像 · ${a.outfit} · 所绘年龄${a.ageRange}`:'旧事中的一刻 · 完整画面'}),'');});}
