function renderTitle(){
 const started=done(state,'M01');
 app.innerHTML=`<section class="title-screen"><picture class="title-cover"><source type="image/webp" srcset="assets/exports/s11-v1/cover-display.webp"><img src="assets/cover.png" alt=""></picture><div class="title-wash"></div><div class="title-body"><span class="title-seal">雍</span><h1>重生长雍帝王赋</h1><p class="title-sub">再睁眼，仍是雍正元年。<br>这一回，江山与故人，都还来得及。</p><div class="title-actions"><button class="primary-btn" data-title-enter>${started?'继续 · '+esc(dateText(state.date)):'开卷'}</button>${started?'<button class="text-btn" data-title-settings>存档与设置</button>':''}</div></div></section>`;
 app.querySelector('[data-title-enter]').onclick=()=>{titleOpen=false;render();window.scrollTo(0,0);};
 app.querySelector('[data-title-settings]')?.addEventListener('click',()=>{titleOpen=false;view='settings';render();});
}
