function showSchedule(cid){if(isWeekly(state)){showWeekPlanner({actor:cid,kind:canMeetOn(state,cid,state.date)?'meet':'letter'});return;}dialog('把约定说清',`<p>${NAMES[cid]} · ${esc(actorPlace(state,cid))}。本版只接受能落在首版窗口内的约定。</p><label class="field">时间<select id="schedule-when"><option value="tomorrow">明日</option><option value="next-month">下月同日</option><option value="next-turn">下一战略回合</option></select></label><label class="field">安排<select id="schedule-purpose"><option value="meet">会面</option><option value="letter">书信往来</option>${cid==='C02'?'<option value="rest">轮值后休息</option>':''}</select></label><p>确认时预留1次安排，履行时不再扣；私聊不会自动代办约见。</p>`,`<button class="primary-btn" id="schedule-preview">核对方案</button>`);$('#schedule-preview').onclick=()=>{const a={type:'promise',actor:cid,when:$('#schedule-when').value,purpose:$('#schedule-purpose').value};closeModal();propose([a]);};}
