const inputDrafts=new Map();
function cancelInput(repaint=true){if(!inputSession.cancel())return;busy=false;if(repaint){render();toast('这次等待已取消；已说出的原句仍在，未提交的安排没有执行。');}}
async function sendInput(form){
 if(busy||committing||state.sealed)return;
 const text=form.elements.input.value.trim();if(!text)return;
 reactions.cancel();const ticket=inputSession.start(),signal=ticket.controller.signal;
 const actor=form.dataset.actor,eventId=form.dataset.eventId||null,originalView=view,originalScene=sceneId,requestGame=state.gameId,parseRevision=state.revision;
 const attitudeDraft=eventId==='M06'?Object.fromEntries([...document.querySelectorAll('[data-main-attitude]')].map(el=>[el.dataset.mainAttitude,el.value])):null;
 const current=()=>inputSession.current(ticket),finish=()=>{if(!inputSession.finish(ticket))return false;busy=false;return true;};
 const unchanged=revision=>state.gameId===requestGame&&state.revision===revision&&view===originalView&&sceneId===originalScene;
 readingDrafts.set(requestGame,actor,eventId,text);let recorded=false;busy=true;
 form.setAttribute('aria-busy','true');form.querySelector('[data-operation-feedback]').textContent='正在听你说，请稍候。';form.elements.input.disabled=true;
 form.querySelector('button[type="submit"]').disabled=true;form.querySelector('button[type="submit"]').textContent='他在听…';form.querySelector('[data-input-cancel]').hidden=false;
 try{
  let parsed=await resolveInput(text,{state,actor,eventId,pendingInput:inputDrafts.get(state.gameId+'|'+actor+'|'+eventId)},getAIConfig().mode==='fixed'?null:input=>parseAI(state,actor,eventId,input,{signal}));
  if(!current())return;
  if(!unchanged(parseRevision)){finish();render();toast('场景已变化，这句话仍未执行。');return;}
  const inputKey=state.gameId+'|'+actor+'|'+eventId;if(parsed.pendingInput)inputDrafts.set(inputKey,parsed.pendingInput);else inputDrafts.delete(inputKey);
  if(attitudeDraft)parsed.actions=parsed.actions.map(a=>a.type==='event'&&a.eventId==='M06'&&!a.params?{...a,params:{attitudes:attitudeDraft}}:a);
  if(parsed.disclosure){finish();render();if(parsed.clarifications.length)dialog('先把这句话说清',parsed.clarifications.map(x=>`<p>${esc(x)}</p>`).join(''),'');else await propose(parsed.actions,{contextNote:'这句话涉及重生秘密。确认前不投递给角色；取消只保留在你的输入草稿里。'});return;}
  await update(s=>{if(!current())throw new RuleError('这次等待已取消。','CANCELLED');let next=recordMessage(s,actor,'player',text);const sourceId=next.messages.at(-1).id;for(const segment of parsed.segments){if(segment.kind==='boundary')next=setBoundary(next,actor,segment.intent,sourceId);if(segment.kind==='preference')next=savePreference(next,actor,segment.text,sourceId);}return next;});
  recorded=true;readingDrafts.clear(requestGame,actor,eventId);if(!current())return;
  if(parsed.clarifications.length){await update(s=>{if(!current())throw new RuleError('这次等待已取消。','CANCELLED');return recordMessage(s,actor,'system',parsed.clarifications.join('\n')+'\n等你说明白，再照你的意思办。');});if(finish())render();return;}
  const replyRevision=state.revision,answer=await replyToSegments(state,actor,eventId,parsed.segments,{askAI:getAIConfig().mode==='fixed'?null:input=>chatAI(state,actor,eventId,input,{withSources:true,signal})});
  if(!current())return;
  if(!unchanged(replyRevision)){finish();render();toast('场景已变化，旧回复没有写入新进度。');return;}
  if(answer){if(answer.error)toast(answer.error);await update(s=>{if(!current())throw new RuleError('这次等待已取消。','CANCELLED');return recordMessage(s,actor,'npc',answer.reply,{fallback:answer.fallback,...(answer.memorySources?{memorySources:answer.memorySources}:{})});});}
  if(!finish())return;render();
  if(parsed.actions.length)await propose(parsed.actions,{contextNote:parsed.actions.map(actionInputLabel).filter(Boolean).join('\n')+'\n'+(parsed.segments.some(x=>x.kind==='preference'||x.kind==='boundary')?'原句中的偏好与明确拒绝已分别记录；取消这份命令不会撤销它们。':'以下仅为候选，尚未执行。请核对金额、执行者和后续事项。')});
 }catch(err){if(!finish())return;render();showError(recorded?{...err,message:(err.message||'接话未完成。')+' 原句已保存，无须重复提交，可接着说。'}:err);}
}
function help(){if(isWeekly(state)){dialog('宫中岁时',`<p>一周有六格可自由安排，日间与晚间各占一格。约定先留出时间和预算，真正去做时才记支出。两格小宴安排在同一天。</p><p>主线和普通回报随日期展开；向后走时遇见约期、月账或要紧的事会停下来。留白无须补课，每季也可再留一个七日延展周。</p><p>固定文本可完成元年至三十年八卷；当前卷封卷后，在“存档—长卷接续”明确复制到下一卷。人物活动、七核心与双扩展按双方当下意愿展开；子女出生、成年、外任、病休与工期都按实际日期。周制档与旧季度档分别保存。</p>`,'');return;}dialog('游玩须知',`<ol class="help-list"><li>先在御案展开主线；处置、相知与回访分别结算。</li><li>每回合有两次主动安排。场景内提问不重复扣次数，新开交谈则占一次。</li><li>七条关系均保留。允礼是果郡王；每条线都可以先相知，也可明确只保持合作。</li><li>普通无代价对白直接回应，正式安排先核对。试写“先拨一半，派张廷玉核账”，要在军需场景执行。</li><li>重生秘密须明确选择听者与范围。普通偏好、正式约定和世界事实分别保存。</li><li>季度入口保留元年至二年的原规则。完整三十年请从周制入口新开，或将旧档显式接续为独立周制副本。</li></ol>`,'');}
