async function showMigrationFrom(raw,{sourceKey=null,label='导入旧档'}={}){
 try{
  const parsed=JSON.parse(raw);
  if(parsed.format==='changyong-migration-bundle'){
   const checked=await inspectMigrationBundle(raw);
   dialog('导入迁移包',`<p>原稿为${dateText(checked.report.date)}${checked.report.sealed?'已封卷':''}；副本当前${dateText(checked.current.date)}，国库${checked.current.treasury}，${checked.current.sealed?'已封卷':'可接续'}。8槽中${checked.nonempty}份非空。</p><p>已校验包内原JSON与副本8槽。导入到独立副本；已存在的副本直接打开，当前进度不替换。</p>`,`<button class="primary-btn" id="confirm-migration-bundle">校验并导入副本</button>`);
   $('#confirm-migration-bundle').onclick=async()=>{const b=$('#confirm-migration-bundle');b.disabled=true;try{const result=await importMigrationBundle(raw);closeModal();showMigrationReady(result);}catch(error){b.disabled=false;showError(error);}};return;
  }
  if(parsed.format==='changyong-local-archive'){
   if(!Array.isArray(parsed.records)||parsed.records.length>32)throw new RuleError('档案集合格式错误。');const records=parsed.records.filter(r=>/^changyong-v12-(auto|previous|import-backup|manual-[0-4])$/.test(r.key)&&typeof r.raw==='string');
   if(!records.length)throw new RuleError('此集合没有季度旧档，可用对应世界入口恢复单档。');
   dialog('选择集合里的旧档',records.map((r,i)=>{let summary;try{const s=parseAnyImport(r.raw);summary=dateText(s.date)+(s.sealed?' · 已封卷':'');}catch{summary='格式需检查，可先保留原文件';}return `<div class="entry"><p>${esc(r.key)}<br>${esc(summary)}</p><button class="secondary-btn" data-migrate-record="${i}">预览这份旧档</button></div>`;}).join(''),'');
   modal.querySelectorAll('[data-migrate-record]').forEach(b=>b.onclick=()=>showMigrationFrom(records[Number(b.dataset.migrateRecord)].raw,{label:'档案集合旧档'}));return;
  }
  const plan=await prepareMigration(raw,{sourceKey,label});const existing=migrationReceipt(plan.copyId);
  if(existing){dialog('这份原稿已有副本','<p>已有副本和它后来走过的进度会继续保留，重复迁移不会重新发奖或重开时间。</p>',`<a class="primary-btn" href="${copyURL(plan.copyId)}">打开已有副本</a>`);return;}
  dialog('核对复制接续',migrationPreviewHTML(plan),'<button class="primary-btn" id="confirm-migration">保留原档，创建副本</button>');
  $('#confirm-migration').onclick=async()=>{const b=$('#confirm-migration');b.disabled=true;try{const result=await commitMigration(plan);closeModal();showMigrationReady(result);}catch(error){b.disabled=false;showError(error);}};
 }catch(error){showError(error instanceof SyntaxError?new RuleError('文件不是有效JSON，原文件未修改。'):error);}
}
function showMigrationReady(result){dialog(result.duplicate?'已有副本已保留':'副本已保存',`<p>原季度档和现有周制新档均保留。可以先下载含原JSON的迁移包，再进入独立副本。</p>`,`<button class="secondary-btn" id="download-ready-bundle">下载迁移包</button><a class="primary-btn" href="${result.url}">进入周制副本</a>`);$('#download-ready-bundle').onclick=()=>{try{download(exportMigrationBundle(result.receipt.copyId),'长雍迁移包_'+result.receipt.copyId.slice(0,8)+'.json');}catch(error){showError(error);}};}
function showLegacySourceList(){const sources=legacySources();dialog('选择本机季度旧档',sources.map((s,i)=>`<div class="entry"><h3>${esc(s.label)}</h3><p>${s.empty?'空槽':s.error?esc(s.error):dateText(s.state.date)+(s.state.sealed?' · 已封卷':' · 可接续')}</p>${s.raw?`<button class="secondary-btn" data-local-migration="${i}" ${s.error?'disabled':''}>预览复制</button><button class="text-btn" data-local-original="${i}">下载原记录</button>`:''}</div>`).join(''),'');modal.querySelectorAll('[data-local-migration]').forEach(b=>b.onclick=()=>{const s=sources[Number(b.dataset.localMigration)];showMigrationFrom(s.raw,{sourceKey:s.key,label:s.label});});modal.querySelectorAll('[data-local-original]').forEach(b=>b.onclick=()=>{const s=sources[Number(b.dataset.localOriginal)];download(s.raw,'长雍原季度档_'+s.key+'.json');});}
async function showContinuationFrom(raw,{key=null}={}){
 try{const parsed=JSON.parse(raw);
  if(['changyong-continuation-bundle','changyong-continuation-gzip'].includes(parsed.format)){
   const checked=await inspectContinuationBundle(raw),auto=parseAnyImport(checked.records.find(r=>r.key.endsWith('-auto')).raw);
   dialog('恢复完整长卷接续包',`<p>副本停在${dateText(auto.date)}。保留原JSON与本副本八槽；已存在时只打开已有进度，不回退。</p>`,'<button class="primary-btn" id="continuation-import-confirm">核对并导入接续包</button>');
   $('#continuation-import-confirm').onclick=async()=>{try{showContinuationReady(await importContinuationBundle(raw));}catch(error){showError(error);}};return;
  }
  const plan=await prepareContinuation(raw,{key});
  dialog(isEighth(plan.target)?'核对第八卷显式接续':isSeventh(plan.target)?'核对第七卷显式接续':isSixth(plan.target)?'核对第六卷显式接续':isFifth(plan.target)?'核对第五卷显式接续':isFourth(plan.target)?'核对第四卷显式接续':'核对第三卷显式接续',`<p>来源封卷停在${dateText(plan.target.weekly.continuation.source.date)}，F00与现有八槽保持。新副本从${isEighth(plan.target)?'二十七年正月一日开始，到三十年末':isSeventh(plan.target)?'二十一年正月一日开始，到二十六年末':isSixth(plan.target)?'十三年正月一日开始，到二十年末':isFifth(plan.target)?'七年正月一日开始，到十二年末':isFourth(plan.target)?'五年正月一日开始，到六年末':'三年正月一日开始，到四年末'}；不补发旧月收入，不增加国库或关系。</p><p>原稿精确另存，新副本另有八槽。重复选择同一原JSON仅打开已有进度。</p>`,`<button class="primary-btn" id="continuation-create-confirm">保留原档，创建${isEighth(plan.target)?'第八':isSeventh(plan.target)?'第七':isSixth(plan.target)?'第六':isFifth(plan.target)?'第五':isFourth(plan.target)?'第四':'第三'}卷副本</button>`);
  $('#continuation-create-confirm').onclick=async()=>{try{showContinuationReady(await commitContinuation(plan));}catch(error){showError(error);}};
 }catch(error){showError(error);}
}
function showContinuationReady(result){dialog(result.duplicate?'已有长卷副本保留':'长卷副本已保存','<p>原入口和原JSON保持。先下载完整接续包，再进入副本。各卷与最终史册按实际已经发生的记录收存。</p>',`<button class="secondary-btn" id="continuation-download-ready">下载完整接续包</button><a class="primary-btn" href="${result.url}">进入长卷副本</a>`);$('#continuation-download-ready').onclick=()=>{try{download(exportContinuationBundle(result.receipt.copyId),'长雍_完整接续包.json');}catch(error){showError(error);}};}
async function recoverCopy(restored,label){
 dialog('恢复这份副本',`<p>${esc(label)}，${dateText(restored.date)}。当前损坏自动档另存原始留档；原季度JSON和其他槽位保留。</p>`,'<button class="primary-btn" id="confirm-copy-recover">保留原始记录并恢复</button>');
 $('#confirm-copy-recover').onclick=async()=>{try{await exclusive(()=>{const raw=localStorage.getItem(STORAGE_KEY);if(raw!==recoveryRaw)throw new RuleError('另一窗口已更新副本，请重新载入。','CONFLICT');if(raw!==null)localStorage.setItem((continuationId?'changyong-continuation-damaged-'+continuationId:'changyong-migration-damaged-'+copyId)+'-'+uid(),raw);const e=saveEnvelope(restored,null,undefined,{force:true});state=e.state;envelopeToken=e.writeId;});initError=null;view=state.sealed?'chronicle':done(state,'M01')?'desk':'scene';sceneId=done(state,'M01')?null:'M01';closeModal();render();toast('副本已恢复，原始留档保留。');}catch(error){showError(error);}};
}

